// ================= 中建史 01 建筑群 =================
function forbiddenAxis() {
  // 紫禁城中轴：南→北
  const N = [
    ['大清门',''],['千步廊',''],['天安门','皋门'],['端门','库门'],['午门','雉门'],['太和门','应门'],
    ['太和殿','外朝·重檐庑殿'],['中和殿','治朝·单檐攒尖'],['保和殿','燕朝·重檐歇山'],['乾清门','路门'],['乾清宫','内廷'],['交泰殿','内廷'],['坤宁宫','内廷'],['御花园',''],['景山','压住前朝风水']];
  const W = 76, x0 = 40, y = 120, w = x0*2 + W*(N.length-1);
  const gates = ['天安门','端门','午门','太和门','乾清门'], halls = ['太和殿','中和殿','保和殿'], palaces = ['乾清宫','交泰殿','坤宁宫'];
  const peaks = [[0,2,'第一高潮','大清门 千步廊 → 天安门'],[2,4,'第二高潮','天安门后庭院 → 端门 → 午门'],[5,6,'第三高潮（全局最高潮）','太和门庭院 → 太和殿']];
  let s = `<svg class="axis-svg" viewBox="0 0 ${w} 250" width="${w}" role="img" aria-label="紫禁城中轴空间序列示意">`;
  s += `<line x1="${x0-20}" y1="${y}" x2="${w-x0+20}" y2="${y}" class="ax-line"/>`;
  s += `<text x="${x0-20}" y="${y+60}" class="ax-cap">南</text><text x="${w-x0+6}" y="${y+60}" class="ax-cap">北</text>`;
  peaks.forEach(([a,b,t,d],i)=>{ const xa = x0+a*W-26, xb = x0+b*W+26, yy = 22+ (i===2?0:0);
    s += `<rect x="${xa}" y="${yy}" width="${xb-xa}" height="44" rx="6" class="pk pk${i}"/><text x="${(xa+xb)/2}" y="${yy+18}" class="pk-t">${t}</text><text x="${(xa+xb)/2}" y="${yy+35}" class="pk-d">${d}</text>`;
    s += `<line x1="${xa}" y1="${yy+44}" x2="${xa}" y2="${y-14}" class="pk-l"/><line x1="${xb}" y1="${yy+44}" x2="${xb}" y2="${y-14}" class="pk-l"/>`; });
  N.forEach(([n,sub],i)=>{ const x = x0+i*W; const k = gates.includes(n)?'g':halls.includes(n)?'h':palaces.includes(n)?'p':'o';
    s += `<g class="ax-n ax-${k}"><circle cx="${x}" cy="${y}" r="${k==='h'?11:k==='g'?8:6}"/><text x="${x}" y="${y+30}" class="ax-t">${n}</text>${sub?`<text x="${x}" y="${y+47}" class="ax-s">${sub}</text>`:''}</g>`; });
  s += `<text x="${x0+2*W}" y="${y+78}" class="ax-cap2">五门：天安门、端门、午门、太和门、乾清门 ↔ 周礼「皋、库、雉、应、路」</text>`;
  s += `<text x="${x0+6*W}" y="${y+100}" class="ax-cap2">三殿（外朝/治朝/燕朝） · 两宫：乾清宫、坤宁宫（+交泰殿）</text></svg>`;
  return `<div class="svgw">${s}</div><div class="legend"><span class="lg lg-g">五门</span><span class="lg lg-h">三大殿</span><span class="lg lg-p">内廷</span><span class="muted">城市轴线 7.5km（永定门—钟楼）；宫前序列+皇城轴线 1.6km（大清门—景山）。示意图按原图文字排序，间距不代表实际距离。</span></div>`;
}
