function pyramidSVG() {
  // 形状为按文字描述画的示意（非比例）
  const st = [
    ['玛斯塔巴','墓室+祀厅', 'M10 70 L18 52 L62 52 L70 70 Z'],
    ['乃伯特卡陵墓','祀厅下 9 层砖台基', (()=>{let d='';for(let i=0;i<9;i++){const w=60-i*4,y=70-i*3.4;d+=`M${40-w/2} ${y} h${w} v-3.4 h-${w} Z `;}return d;})()],
    ['昭赛尔陵墓','阶梯形 **6 层**', (()=>{let d='';for(let i=0;i<6;i++){const w=64-i*10,y=70-i*9;d+=`M${40-w/2} ${y} h${w} v-9 h-${w} Z `;}return d;})()],
    ['麦登金字塔','**3 层**', 'M10 70 h60 v-14 h-60 Z M18 56 h44 v-16 h-44 Z M27 40 h26 v-18 h-26 Z'],
    ['达舒尔金字塔','两段，**上下段坡度不同**（折线形）', 'M6 70 L22 38 L40 18 L58 38 L74 70 Z'],
    ['吉萨金字塔群','**精确的正方锥**，最成熟', 'M4 70 L40 12 L76 70 Z'],
  ];
  return `<div class="pyr">${st.map(([n,d,p],i)=>`${i?'<div class="fl-ar">→</div>':''}<figure class="pyr-i${i===5?' hl':''}"><svg viewBox="0 0 80 74" aria-hidden="true"><path d="${p}"/><line x1="0" y1="70.5" x2="80" y2="70.5"/></svg><figcaption><b>${esc(n)}</b><span>${fmt(d)}</span></figcaption></figure>`).join('')}</div><p class="foot">剖面轮廓按原图文字描述绘制的示意，不按比例。</p>`;
}
function gizaBars() {
  const D = [['胡夫金字塔',146.6,230.35],['哈夫拉金字塔',143.5,215.25],['门卡乌拉金字塔',66.4,108.04]];
  const max = 240, W = 520, rowH = 54;
  let s = `<svg viewBox="0 0 ${W} ${D.length*rowH+30}" class="bars" role="img" aria-label="吉萨三座金字塔高度与底边长">`;
  D.forEach(([n,h,b],i)=>{ const y = 10+i*rowH, sx = v => v/max*(W-170);
    s += `<text x="0" y="${y+20}" class="b-n">${n}</text>`;
    s += `<rect x="120" y="${y+4}" width="${sx(h)}" height="16" class="b-h"/><text x="${124+sx(h)}" y="${y+17}" class="b-v"><tspan class="m m-n">${h}m</tspan> 高</text>`;
    s += `<rect x="120" y="${y+24}" width="${sx(b)}" height="16" class="b-b"/><text x="${124+sx(b)}" y="${y+37}" class="b-v"><tspan class="m m-n">${b}m</tspan> 底边</text>`; });
  return s + `</svg>`;
}
function templeAxis() {
  const seg = [['高大的门','外部艺术重点：群众性仪式，富丽堂皇'],['围柱式院落',''],['大殿','内部艺术重点：幽暗而威压'],['一串密室','']];
  let s = `<svg viewBox="0 0 560 170" class="temple" role="img" aria-label="太阳神庙纵轴示意">`;
  const xs=[20,150,290,420], ws=[110,120,110,120];
  // 屋顶逐层降低、地面逐层升高
  const roof=[30,52,66,80], floor=[140,134,128,122];
  xs.forEach((x,i)=>{ s+=`<rect x="${x}" y="${roof[i]}" width="${ws[i]}" height="${floor[i]-roof[i]}" class="tp-r${i}"/><text x="${x+ws[i]/2}" y="${floor[i]+18}" class="tp-t">${seg[i][0]}</text>`; });
  s+=`<path d="M20 26 L540 76" class="tp-arrow"/><text x="300" y="38" class="tp-c">屋顶逐层降低 ↘</text><path d="M20 146 L540 118" class="tp-arrow"/><text x="380" y="166" class="tp-c">地面逐层升高 ↗ · 侧墙逐层内收</text></svg>`;
  return `<div class="svgw">${s}</div><p class="foot">示意：空间逐层缩小 → 越压抑、越神秘。实例：卡纳克、鲁克索（尼罗河东岸；金字塔在西岸）。</p>`;
}
