const pkey = r => r[3] || r[1];
function personsOf(periods) {
  const map = new Map();
  P1.filter(r => periods.includes(r[0])).forEach(r => { const k = pkey(r);
    if (!map.has(k)) map.set(k, {n:r[1], g:[], w:[]}); const p = map.get(k);
    if (!p.g.includes(r[0])) p.g.push(r[0]); p.w.push(periods.length > 1 ? `〔${r[0]}〕${r[2]}` : r[2]); });
  return [...map.values()].map(p => ({n:p.n, g:p.g.map(x=>'p'+periods.indexOf(x)), w:p.w.join('；')}));
}
function stPeter() {
  const S = [['伯拉孟特',1],['拉斐尔',0],['帕鲁齐',1,'未果'],['小桑加洛',0,'东部近伯拉孟特'],['米开朗基罗',1,'设计穹顶'],['维尼奥拉',null,'四角小穹顶'],['泡达、封丹纳',null,'完成穹顶'],['玛丹纳',0,'加长前部']];
  const W = 640, x = i => 50 + i*78, y = v => v===1 ? 40 : v===0 ? 120 : 80;
  let pts = [], s = `<svg viewBox="0 0 ${W} 200" class="stp" role="img" aria-label="圣彼得大教堂 8 步平面变化">`;
  s += `<text x="4" y="44" class="stp-l">集中式</text><text x="4" y="124" class="stp-l">拉丁十字</text><line x1="44" y1="40" x2="${W}" y2="40" class="stp-g"/><line x1="44" y1="120" x2="${W}" y2="120" class="stp-g"/>`;
  let last = null;
  S.forEach(([n,v,d],i)=>{ const vv = v===null ? last : v; if (v!==null) last = v; pts.push([x(i), y(vv)]); });
  s += `<polyline points="${pts.map(p=>p.join(',')).join(' ')}" class="stp-p"/>`;
  S.forEach(([n,v,d],i)=>{ const [px,py] = pts[i];
    s += `<circle cx="${px}" cy="${py}" r="${v===null?5:8}" class="${v===1?'c1':v===0?'c0':'cn'}"/><text x="${px}" y="${py+ (py>80?-14:22)}" class="stp-n">${'①②③④⑤⑥⑦⑧'[i]}</text><text x="${px}" y="160" class="stp-t">${n}</text>${d?`<text x="${px}" y="178" class="stp-d">${d}</text>`:''}`; });
  return `<div class="svgw">${s}</div><p class="foot">实心大点＝平面改动；小点＝未改平面（只做穹顶）。2023-21：阿尔伯蒂、达·芬奇**没参与**。</p>`;
}
function pritzker() {
  const D = [['约翰逊',1979],['斯特林',1981],['贝聿铭',1983],['迈耶',1984],['盖里',1989],['西扎',1992],['安藤',1995],['福斯特',1999],['库哈斯',2000],['赫佐格与德梅隆',2001],['扎哈',2004]];
  const W = 680, x = yr => 30 + (yr-1978)*(W-60)/27;
  let s = `<svg viewBox="0 0 ${W} 130" class="prz" role="img" aria-label="普利兹克奖年份"><line x1="20" y1="60" x2="${W-10}" y2="60" class="prz-ax"/>`;
  [1980,1990,2000].forEach(y=>{ s+=`<text x="${x(y)}" y="78" class="prz-y">${y}</text><line x1="${x(y)}" y1="56" x2="${x(y)}" y2="64" class="prz-ax"/>`; });
  D.forEach(([n,yr],i)=>{ const up = i%2===0; s += `<circle cx="${x(yr)}" cy="60" r="5" class="prz-c"/><line x1="${x(yr)}" y1="${up?55:65}" x2="${x(yr)}" y2="${up?34:96}" class="prz-l"/><text x="${x(yr)}" y="${up?28:110}" class="prz-n">${n}</text><text x="${x(yr)}" y="${up?14:124}" class="prz-v"><tspan class="m m-n">${yr}</tspan></text>`; });
  return `<div class="svgw">${s + '</svg>'}</div>`;
}
