AFTER.wj01 = root => {
  const wrap = root.querySelector('#rg-wrap'); if (!wrap) return;
  const draw = i => {
    let groups, persons;
    if (i === 'x') {
      const all = personsOf(periods1()); persons = all.filter(p => p.g.length > 1 || /加尼埃/.test(p.n));
      const used = [...new Set(persons.flatMap(p=>p.g))].sort((a,b)=>+a.slice(1)-+b.slice(1));
      groups = used.map(k => ({k, n:periods1()[+k.slice(1)]}));
    } else { const per = BANDS[i][1]; groups = per.map((p,j)=>({k:'p'+j, n:p})); persons = personsOf(per); }
    wrap.innerHTML = relGraphHTML('wj01', groups, persons, '点左侧流派/时期或右侧人物高亮；红线＝同一人出现在多个时期/流派。');
    applyMaskCount(); mountRG(root, 'wj01');
  };
  const periods1 = () => [...new Set(P1.map(r=>r[0]))];
  root.querySelectorAll('[data-band]').forEach(b => b.onclick = () => { root.querySelectorAll('[data-band]').forEach(x=>x.classList.toggle('on', x===b)); draw(b.dataset.band === 'x' ? 'x' : +b.dataset.band); });
  draw(4);
  const q = root.querySelector('#p1q');
  if (q) q.oninput = () => { const v = q.value.trim(); root.querySelectorAll('.kv-people tr').forEach(tr => {
    let any = false; tr.querySelectorAll('.ln').forEach(l => { const hit = !v || l.textContent.includes(v); l.style.display = hit ? '' : 'none'; any = any || hit; });
    tr.style.display = any || tr.firstElementChild.textContent.includes(v) ? '' : 'none'; }); };
};
