  op.forEach((r,i)=>{ svg += `<circle cx="${xs(i)}" cy="${ys(lv[r[5]])}" r="6" class="op-c"/><text x="${xs(i)}" y="${H+8}" class="op-n">${r[1].replace('广场','').replace('群','')}</text><text x="${xs(i)}" y="${H+24}" class="op-e">${r[0]}</text>`; });
