function eclectic(name, parts) {
  const C = {'法国古典主义':'c1','巴洛克':'c2','古罗马':'c3','拜占庭':'c4','古希腊':'c5','哥特':'c6','文艺复兴':'c7'};
  return `<div class="ecl"><div class="ecl-h">${fmt('{w|'+name+'}')}</div><div class="ecl-b">${parts.map(([el,st])=>`<div class="ecl-i ${C[st]||''}"><span>${esc(el)}</span><b>${fmt('{t|'+st+'}')}</b></div>`).join('')}</div></div>`;
}
