RENDER.wj06 = () => {
  const att = ['激烈对抗','温和对抗','改良'];
  const spec = `<div class="spec">${att.map((a,i)=>`<div class="spec-z z${i}"><div class="spec-h">${a}</div><div class="spec-c">${S6.filter(s=>s[0]===a).map(s=>`<div class="spec-s">${esc(s[1])}</div>`).join('')}</div></div>`).join('')}</div><div class="spec-ax"><span>← 与现代主义对抗更强</span><span>更接近继承改良 →</span></div>`;
  const pm = {}; S6.forEach((s,i)=>s[3].forEach(([p,w])=>{ (pm[p] = pm[p] || {n:p,g:new Set(),w:[]}); pm[p].g.add('s'+i); pm[p].w.push(`{w|${w}}`); }));
  // 加入战后七大思潮中的同名人物，体现跨阶段
  const extra = [['菲利普·约翰逊','典雅主义（战后）：谢尔登艺术纪念馆'],['罗杰斯','注重高度工业技术（战后）：蓬皮杜中心']];
  const persons = Object.values(pm).map(p=>({n:p.n, g:[...p.g], w:p.w.join('；') + (extra.find(e=>e[0]===p.n)?'；〔战后〕'+extra.find(e=>e[0]===p.n)[1]:'')}));
  return sec('spec','对现代主义的态度：三分法光谱', spec)
  + sec('mx','七流派横向矩阵', mx({wide:true, cols:['对比项', ...S6.map(s=>s[1])], rows:[['态度', ...S6.map(s=>s[0])],['特点（key）', ...S6.map(s=>'{t|'+s[2].replace(/\{[^}]*\}/g,'')+'}')],['人物 → 作品', ...S6.map(s=>s[3].map(([p,w])=>w.startsWith('《')?`${p}：${w}`:`${p}：{w|${w}}`))]]}) + `<p class="foot">特点栏勘误：{?25}{?27}</p>`.replace(/\{\?(\d+)\}/g,(m,n)=>issueBadge(+n)))
  + sec('graph','人物—流派关系图（跨派）', relGraphHTML('wj06', S6.map((s,i)=>({k:'s'+i,n:s[1]})), persons, '艾森曼：解构 + 新现代；格雷夫斯：早期新现代、后期后现代。'))
  + sec('getty','论述可用：格蒂中心（2024 外建 10 分）', defs([['格蒂中心（迈耶里程碑之作）','建筑群落与环境时而主宰、时而被环境控制，在相互融合中合二为一；回到古罗马哈德良离宫的精神——空间序列、厚重墙体、秩序感、建筑与场地互为依存。被称作**当代的雅典卫城**。']])
    + kv([['文丘里','「Less is bore」少即厌烦，对 less is more 的否定；《建筑的复杂性与矛盾性》：批判现代建筑技术理性，提倡向历史吸取经验；《向拉斯维加斯学习》：关注商业文化景观'],['詹克斯','1972.7.15 现代主义死亡；《后现代主义建筑语言》'],['罗西《城市建筑》','城市中的建筑需要融入历史、城市形态和记忆来诠释'],['霍尔《锚固》','任何基地都自有一种存在和意义，建筑应在这些特殊性中生成']]))
  + sec('confuse','易混点', pits(['隐喻主义属**后现代主义**（2008）。','《后现代建筑语言》是**詹克斯**，不是文丘里（2009）。','鸟巢不是极简主义（原图注：高技派/结构主义）；路易斯·康、卒姆托原图列在极简主义栏但空着 {?14}。','新理性主义的代表是罗西与克里尔兄弟（2022 真题；克里尔兄弟原图未列）。']));
};
