  C.forEach(([n,y],i)=>{ const up=i%2===0; s += `<circle cx="${x(y)}" cy="60" r="6" class="prz-c"/><line x1="${x(y)}" y1="${up?54:66}" x2="${x(y)}" y2="${up?36:86}" class="prz-l"/><text x="${x(y)}" y="${up?30:100}" class="prz-n">《${n}》</text><text x="${x(y)}" y="${up?14:116}" class="prz-v"><tspan class="m m-n">${y}</tspan></text>`; });
  s += '</svg>';
  return sec('charter','20 世纪规划宪章年份轴', `<div class="svgw">${s}</div>` + mx({cols:['宪章','年份','要点'], rows:C.map(c=>[`《${c[0]}》`, String(c[1]), c[2]])}))
